Here is the commit message:
f2fs: do not allow to decompress files have
 FI_COMPRESS_RELEASED

If a file has FI_COMPRESS_RELEASED, all writes for it should not be
allowed. However, as of now, in case of compress_mode=user, writes
triggered by IOCTLs like F2FS_IOC_DE/COMPRESS_FILE are allowed unexpectly,
which could crash that file.
To fix it, let's do not allow F2FS_IOC_DE/COMPRESS_IOCTL if a file already
has FI_COMPRESS_RELEASED flag.

This is the reproduction process:
1.  $ touch ./file
2.  $ chattr +c ./file
3.  $ dd if=/dev/random of=./file bs=4096 count=30 conv=notrunc
4.  $ dd if=/dev/zero of=./file bs=4096 count=34 seek=30 conv=notrunc
5.  $ sync
6.  $ do_compress ./file      ; call F2FS_IOC_COMPRESS_FILE
7.  $ get_compr_blocks ./file ; call F2FS_IOC_GET_COMPRESS_BLOCKS
8.  $ release ./file          ; call F2FS_IOC_RELEASE_COMPRESS_BLOCKS
9.  $ do_compress ./file      ; call F2FS_IOC_COMPRESS_FILE again
10. $ get_compr_blocks ./file ; call F2FS_IOC_GET_COMPRESS_BLOCKS again

This reproduction process is tested in 128kb cluster size.
You can find compr_blocks has a negative value.

Fixes: 5fdb322ff2c2b ("f2fs: add F2FS_IOC_DECOMPRESS_FILE and F2FS_IOC_COMPRESS_FILE")

Signed-off-by: Junbeom Yeom <junbeom.yeom@samsung.com>
Signed-off-by: Sungjong Seo <sj1557.seo@samsung.com>
Signed-off-by: Youngjin Gil <youngjin.gil@samsung.com>
Signed-off-by: Jaewook Kim <jw5454.kim@samsung.com>
Reviewed-by: Chao Yu <chao@kernel.org>
Signed-off-by: Jaegeuk Kim <jaegeuk@kernel.org>

Here is the root cause:
The bug arises from the fact that files marked with the `FI_COMPRESS_RELEASED` flag were still allowed to undergo compression and decompression operations via IOCTLs like `F2FS_IOC_DECOMPRESS_FILE` and `F2FS_IOC_COMPRESS_FILE`. This could lead to unexpected behavior, such as negative values in compression block counts, potentially crashing the file due to invalid state changes.

Here is the patch:

 static int f2fs_ioc_decompress_file(struct file *filp, unsigned long arg)
 {
 	struct inode *inode = file_inode(filp);
 	struct f2fs_sb_info *sbi = F2FS_I_SB(inode);
 	struct f2fs_inode_info *fi = F2FS_I(inode);
 	pgoff_t page_idx = 0, last_idx;
 	unsigned int blk_per_seg = sbi->blocks_per_seg;
 	int cluster_size = fi->i_cluster_size;
 	int count, ret;

 	if (!f2fs_sb_has_compression(sbi) ||
 			F2FS_OPTION(sbi).compress_mode != COMPR_MODE_USER)
 		return -EOPNOTSUPP;

 	if (!(filp->f_mode & FMODE_WRITE))
 		return -EBADF;

 	if (!f2fs_compressed_file(inode))
 		return -EINVAL;

 	f2fs_balance_fs(F2FS_I_SB(inode), true);

 	file_start_write(filp);
 	inode_lock(inode);

 	if (!f2fs_is_compress_backend_ready(inode)) {
 		ret = -EOPNOTSUPP;
 		goto out;
 	}

+	if (is_inode_flag_set(inode, FI_COMPRESS_RELEASED)) {
+		ret = -EINVAL;
+		goto out;
+	}
+
 	ret = filemap_write_and_wait_range(inode->i_mapping, 0, LLONG_MAX);
 	if (ret)
 		goto out;

 	if (!atomic_read(&fi->i_compr_blocks))
 		goto out;

 	last_idx = DIV_ROUND_UP(i_size_read(inode), PAGE_SIZE);

 	count = last_idx - page_idx;
 	while (count) {
 		int len = min(cluster_size, count);

 		ret = redirty_blocks(inode, page_idx, len);
 		if (ret < 0)
 			break;

 		if (get_dirty_pages(inode) >= blk_per_seg)
 			filemap_fdatawrite(inode->i_mapping);

 		count -= len;
 		page_idx += len;
 	}

 	if (!ret)
 		ret = filemap_write_and_wait_range(inode->i_mapping, 0,
 							LLONG_MAX);

 	if (ret)
 		f2fs_warn(sbi, "%s: The file might be partially decompressed (errno=%d). Please delete the file.",
 			  __func__, ret);
 out:
 	inode_unlock(inode);
 	file_end_write(filp);

 	return ret;
 }

 static int f2fs_ioc_compress_file(struct file *filp, unsigned long arg)
 {
 	struct inode *inode = file_inode(filp);
 	struct f2fs_sb_info *sbi = F2FS_I_SB(inode);
 	pgoff_t page_idx = 0, last_idx;
 	unsigned int blk_per_seg = sbi->blocks_per_seg;
 	int cluster_size = F2FS_I(inode)->i_cluster_size;
 	int count, ret;

 	if (!f2fs_sb_has_compression(sbi) ||
 			F2FS_OPTION(sbi).compress_mode != COMPR_MODE_USER)
 		return -EOPNOTSUPP;

 	if (!(filp->f_mode & FMODE_WRITE))
 		return -EBADF;

 	if (!f2fs_compressed_file(inode))
 		return -EINVAL;

 	f2fs_balance_fs(F2FS_I_SB(inode), true);

 	file_start_write(filp);
 	inode_lock(inode);

 	if (!f2fs_is_compress_backend_ready(inode)) {
 		ret = -EOPNOTSUPP;
 		goto out;
 	}

+	if (is_inode_flag_set(inode, FI_COMPRESS_RELEASED)) {
+		ret = -EINVAL;
+		goto out;
+	}
+
 	ret = filemap_write_and_wait_range(inode->i_mapping, 0, LLONG_MAX);
 	if (ret)
 		goto out;

 	set_inode_flag(inode, FI_ENABLE_COMPRESS);

 	last_idx = DIV_ROUND_UP(i_size_read(inode), PAGE_SIZE);

 	count = last_idx - page_idx;
 	while (count) {
 		int len = min(cluster_size, count);

 		ret = redirty_blocks(inode, page_idx, len);
 		if (ret < 0)
 			break;

 		if (get_dirty_pages(inode) >= blk_per_seg)
 			filemap_fdatawrite(inode->i_mapping);

 		count -= len;
 		page_idx += len;
 	}

 	if (!ret)
 		ret = filemap_write_and_wait_range(inode->i_mapping, 0,
 							LLONG_MAX);

 	clear_inode_flag(inode, FI_ENABLE_COMPRESS);

 	if (ret)
 		f2fs_warn(sbi, "%s: The file might be partially compressed (errno=%d). Please delete the file.",
 			  __func__, ret);
 out:
 	inode_unlock(inode);
 	file_end_write(filp);

 	return ret;
 }



